import React, { useState } from 'react';
import { ChevronDown, ChevronRight, CheckCircle2, Sparkles, Sparkle, Mail } from 'lucide-react';

const initialQuestions = [
  {
    id: 1,
    title: 'How do I make a reservation?',
    answer: 'Simply click the "Reserve Table" button on our live calendar. Select your date, time, and party size. We’ll confirm via email and text.',
    isExpanded: false
  },
  {
    id: 2,
    title: 'What’s your cancellation policy?',
    answer: '24-hour advance notice is required for no-shows or cancellations. No-shows without notice will be charged the full reservation amount.',
    isExpanded: false
