    isExpanded: false
  },
  {
    id: 4,
    title: 'Do you offer delivery?',
    answer: 'Yes, our partner delivery service ensures your meal arrives hot and fresh. Delivery fees apply starting from $5.',
    isExpanded: false
  },
  {
    id: 5,
    title: 'What payment methods do you accept?',
    answer: 'We accept major credit cards, Apple Pay, Google Pay, and Venmo. We also offer an exclusive loyalty rewards program.',
    isExpanded: false
  }
];

export default function Faq() {
  const [questions, setQuestions] = useState(initialQuestions);
  const [activeId, setActiveId] = useState(null);

  const toggle = (id) => {
    setQuestions((prev) => prev.map((q) => ({ ...q, isExpanded: q.id === id ? !q.isExpanded : false })));
    setActiveId(id);
  };

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 flex items-center justify-center p-4 sm:p-6 lg:p-8">
      <div className="w-full max-w-2xl overflow-hidden rounded-2xl bg-white/5 backdrop-blur-xl border border-white/10 p-8 shadow-2xl transition-all duration-300 hover:shadow-4xl">

        {/* Header Bar */}
        <div className="flex items-center justify-between mb-8">
          <div className="flex items-center space-x-2">
            <div className="p-2 rounded-xl bg-indigo-500/10 text-indigo-400 shadow-inner">
              <Sparkles className="w-5 h-5 animate-pulse" />
            </div>
            <div>
              <h2 className="text-xl font-bold tracking-tight text-slate-200">Frequently Asked Questions</h2>
              <p className="text-xs text-slate-400">Answers to the most common queries</p>
            </div>
          </div>
          <button className="self-start sm:self-auto flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-white/5 text-slate-400 border border-white/10 hover:text-slate-200 hover:bg-white/15 transition-colors active:scale-95">
            <span>View All</span>
            <Sparkle className="w-4 h-4 text-indigo-400" />
          </button>
        </div>

        {/* Accordion List */}
        <div className="space-y-4">
          {questions.map((q) => (
            <div 
              key={q.id}
              className="group relative border border-white/5 rounded-xl bg-white/5 p-6 transition-all duration-300 hover:border-white/10 hover:bg-white/10"
            >
              <div className="flex items-center justify-between gap-3 pb-3 border-b border-white/5 mb-3">
                <div className="flex-1">
                  <h3 className="font-semibold text-slate-400 group-hover:text-indigo-300 transition-colors">{q.title}</h3>
                  <p className="text-xs text-slate-500">{q.answer}</p>
                </div>
                <button
                  onClick={() => toggle(q.id)}
                  className="w-8 h-8 rounded-lg border border-white/10 bg-white/5 p-1.5 transition-all duration-200 hover:bg-white/10 active:scale-95"
                >
                  <ChevronRight 
                    className={`w-4 h-4 transition-transform group-hover:rotate-180 duration-300 ${q.isExpanded ? 'rotate-90' : ''}`}
                  />
                </button>
              </div>
              {q.isExpanded && (
                <div className="p-4 border-t border-white/5">
                  {q.answer}
                </div>
              )}
            </div>
          ))}
        </div>

        {/* Decorative Gradient Decorative Bar */}
        <div className="w-full bg-gradient-to-r from-indigo-500 via-purple-500 to-pink-500 h-1 rounded-xl mt-8 mb-6" />

        {/* Social Proof Feedback */}
        <div className="flex items-center justify-between pb-8 pt-6 border-t border-white/5">
          <div className="flex items-center gap-2">
            <div className="p-2 rounded-xl bg-white/5 text-slate-400 shadow-inner">
              <Sparkles className="w-4 h-4" />
            </div>
            <div>
              <h3 className="text-sm font-medium text-slate-400">We’re always here to help!</h3>
              <p className="text-xs text-slate-500">Drop us a line for more info or to book your table.</p>
            </div>
          </div>
          <button className="inline-flex items-center gap-1.5 px-4 py-2 rounded-xl bg-white/5 text-slate-400 border border-white/10 hover:text-indigo-300 hover:bg-white/10 transition-colors active:scale-95">
            <Mail className="w-4 h-4" />
            <span>Contact Us</span>
          </button>
        </div>

      </div>
    </div>
  );
}

